import { writeOutput } from "./codegen";

const DOCS_URL = "https://topvisor.com/api/v2/first-call/";
const USER_ID_PLACEHOLDER = "100001";
const TOKEN_PLACEHOLDER =
  "CoffeeSafeLocalCoffeeSafeLocalCoffeeSafeLocalCoffeeSafeLocal";

function generateTypeScript(): string {
  const lines: string[] = [
    "// Auto-generated from Topvisor API v2 docs.",
    `// Source: ${DOCS_URL}`,
    "// Regenerate: cd turbo && pnpm -F @vm0/firewalls-generator generate:topvisor",
    "//",
    "// DO NOT EDIT THIS FILE MANUALLY.",
    "",
    'import type { FirewallConfig } from "../firewall-types";',
    "",
    "export const topvisorFirewall = {",
    '  name: "topvisor",',
    '  description: "Topvisor",',
    "  placeholders: {",
    `    TOPVISOR_USER_ID: "${USER_ID_PLACEHOLDER}",`,
    `    TOPVISOR_TOKEN: "${TOKEN_PLACEHOLDER}",`,
    "  },",
    "  apis: [",
    "    {",
    '      base: "https://api.topvisor.com",',
    "      auth: {",
    "        headers: {",
    '          "User-Id": "${{ secrets.TOPVISOR_USER_ID }}",',
    '          Authorization: "bearer ${{ secrets.TOPVISOR_TOKEN }}",',
    "        },",
    "      },",
    "      permissions: [],",
    "    },",
    "  ],",
    "} as const satisfies FirewallConfig;",
    "",
  ];
  return lines.join("\n");
}

export async function generate(): Promise<void> {
  console.error("Generating Topvisor firewall config...");
  const ts = generateTypeScript();
  writeOutput("topvisor", ts);
}
